svg.script:
(function () {
  var frame = document.getElementById("app");
  var base = new URL("./", document.URL).href; // folder this file lives in

  function fail(message) {
    frame.srcdoc =
      "<body style='background:#000;color:#ff8a80;font:16px sans-serif;padding:24px'>" +
      message + "</body>";
  }

  fetch(base + "index.html", { cache: "no-cache" })
    .then(function (r) {
      if (!r.ok) throw new Error("HTTP " + r.status);
      return r.text();
    })
    .then(function (html) {
      var tag = '<base href="' + base + '">';
      frame.srcdoc = /<head>/i.test(html)
        ? html.replace(/<head>/i, "<head>" + tag)
        : tag + html;
    })
    .catch(function (e) {
      fail("Couldn't load the app: " + e.message);
    });
})();
